// Tests: autogenerated (tests/auto_<table>.json) and custom (tests/<table>.json), run in a
// transaction that is rolled back.
import { api, esc, attempt, dialog, confirmAction, method, statusClass, json, toast } from "../ui.js";

let state = { tests: [], errors: [], files: {}, results: {}, filter: "" };

const EXAMPLE = {
  description: "Describe what the test checks",
  steps: [
    { "POST /my_table": { column: "value" }, as: 1, save: { id: "lastId" } },
    { "GET /my_table/${id}": null, expect: { row: { column: "value" } } },
    { "DELETE /my_table/${id}": null, as: 2, expect: 403 },
  ],
};

export async function render(main, app) {
  main.innerHTML = `
    <h1>Tests</h1>
    <p class="uk-text-muted">Each test runs inside a transaction that is rolled back: the database is left as it was.
      They can also be run in the console with <code>silence test</code>.</p>
    <div class="sa-toolbar">
      <button class="uk-button uk-button-primary" type="button" id="run">Run all</button>
      <button class="uk-button uk-button-default" type="button" id="generate">Generate from the endpoints</button>
      <button class="uk-button uk-button-default" type="button" id="new">New composed test</button>
      <button class="uk-button uk-button-default" type="button" id="export">Export .http</button>
      <span class="sa-toolbar__spacer"></span>
      <span id="summary"></span>
      <label class="uk-text-muted" for="filter">Table</label>
      <select class="uk-select" id="filter"><option value="">All</option></select>
    </div>
    <div id="errors"></div>
    <div id="list"></div>`;

  main.querySelector("#generate").addEventListener("click", async () => {
    const ok = await confirmAction("Generate the tests",
      "The files tests/auto_<table>.json are written again from the endpoints and the current data. " +
      "The custom tests (tests/<table>.json) are kept.", "Generate");
    if (!ok) return;
    const res = await attempt(() => api("/tests/generate", "POST", {}));
    if (res) {
      toast(`${res.tables.reduce((a, t) => a + t.tests, 0)} tests generated`, "success");
      state.results = {};
      await app.refreshStatus();
      load(main);
    }
  });
  main.querySelector("#run").addEventListener("click", () => run(main, null));
  main.querySelector("#new").addEventListener("click", () => edit(main, null));
  main.querySelector("#export").addEventListener("click", async () => {
    const res = await attempt(() => api("/tests/export", "POST", { format: "http" }));
    if (res) {
      toast(`Written: ${res.files.join(", ")}. Open them with VS Code's REST Client: sending them changes the database.`, "success");
    }
  });
  main.querySelector("#filter").addEventListener("change", (e) => {
    state.filter = e.target.value;
    draw(main);
  });
  load(main);
}

async function load(main) {
  const res = await attempt(() => api("/tests"));
  if (!res) return;
  state.tests = res.tests;
  state.errors = res.errors;
  state.files = res.files;
  const tables = [...new Set(res.tests.map((t) => t.table))].sort();
  main.querySelector("#filter").innerHTML = `<option value="">All</option>` +
    tables.map((t) => `<option ${t === state.filter ? "selected" : ""}>${esc(t)}</option>`).join("");
  draw(main);
}

async function run(main, names) {
  const button = main.querySelector("#run");
  button.disabled = true;
  button.innerHTML = `<span uk-spinner="ratio: .6"></span> Running…`;
  const visible = names ?? (state.filter ? state.tests.filter((t) => t.table === state.filter).map((t) => t.name) : null);
  const res = await attempt(() => api("/tests/run", "POST", { names: visible }));
  button.disabled = false;
  button.textContent = "Run all";
  if (!res) return;
  for (const r of res.results) {
    state.results[r.name] = r;
  }
  const passed = res.results.filter((r) => r.passed).length;
  toast(`${passed} of ${res.results.length} tests passed`, passed === res.results.length ? "success" : "warning");
  draw(main);
}

function draw(main) {
  main.querySelector("#errors").innerHTML = state.errors.length
    ? `<div class="uk-alert uk-alert-danger"><strong>Tests not loaded</strong>
        <ul>${state.errors.map((e) => `<li>${esc(e)}</li>`).join("")}</ul></div>` : "";
  const results = Object.values(state.results);
  const passed = results.filter((r) => r.passed).length;
  main.querySelector("#summary").innerHTML = results.length
    ? `<span class="${passed === results.length ? "sa-pass" : "sa-fail"}">${passed} / ${results.length} passed</span>` : "";

  const tests = state.tests.filter((t) => !state.filter || t.table === state.filter);
  const list = main.querySelector("#list");
  if (!tests.length) {
    list.innerHTML = `<p class="uk-text-muted">No tests yet: generate them from the endpoints.</p>`;
    return;
  }
  const byTable = {};
  for (const t of tests) {
    (byTable[t.table] ??= []).push(t);
  }
  list.innerHTML = Object.entries(byTable).sort().map(([table, items]) => `
    <section class="sa-section">
      <h2>${esc(table)}</h2>
      <div class="uk-overflow-auto"><table class="uk-table uk-table-divider uk-table-small uk-table-hover sa-table">
        <thead><tr><th>Result</th><th>Test</th><th>File</th><th></th></tr></thead>
        <tbody>${items.map(row).join("")}</tbody>
      </table></div>
    </section>`).join("");

  for (const button of list.querySelectorAll("[data-action]")) {
    const t = state.tests.find((x) => x.name === button.dataset.name);
    button.addEventListener("click", () => actions[button.dataset.action](main, t));
  }
}

function row(t) {
  const r = state.results[t.name];
  const result = !r ? `<span class="uk-text-muted">—</span>` : r.passed ? `<span class="sa-pass">PASS</span>` : `<span class="sa-fail">FAIL</span>`;
  const first = t.first ?? {};
  const badge = t.source === "auto" ? `<span class="uk-label sa-label-auto">auto</span>` : `<span class="uk-label">custom</span>`;
  return `
    <tr>
      <td>${result}</td>
      <td><strong>${esc(t.name)}</strong> ${t.composite ? `<span class="uk-label sa-label-auto">${t.steps.length} steps</span>` : ""}<br>
        <span class="sa-small">${method(first.method ?? "GET")} <span class="sa-route">${esc(first.path)}</span></span><br>
        <span class="uk-text-muted sa-small">${esc(t.description)}</span>
        ${r && !r.passed ? stepsDetail(r.steps) : ""}</td>
      <td class="sa-small">${badge}<br>${esc(t.file)}.json</td>
      <td class="sa-actions">
        <button class="uk-button uk-button-primary uk-button-small" type="button" data-action="run" data-name="${esc(t.name)}">Run</button>
        ${t.source === "auto"
          ? `<button class="uk-button uk-button-default uk-button-small" type="button" data-action="customize" data-name="${esc(t.name)}">Customize</button>`
          : `<button class="uk-button uk-button-default uk-button-small" type="button" data-action="edit" data-name="${esc(t.name)}">Edit</button>
             <button class="uk-button uk-button-danger uk-button-small" type="button" data-action="remove" data-name="${esc(t.name)}">Delete</button>`}
      </td>
    </tr>`;
}

function stepsDetail(steps) {
  return steps.map((s) => `
    <div class="sa-step ${s.passed ? "sa-step--pass" : "sa-step--fail"} sa-small">
      Step ${s.index + 1}: ${method(s.method)} <span class="sa-route">${esc(s.path)}</span>
      ${s.status ? `→ <span class="sa-status ${statusClass(s.status)}">${s.status}</span>` : ""}
      ${s.failures.length ? `<br>${s.failures.map(esc).join("<br>")}
        <details><summary>Response</summary><pre class="sa-pre uk-margin-small">${json(s.response)}</pre></details>` : ""}
    </div>`).join("");
}

const actions = {
  run(main, t) {
    run(main, [t.name]);
  },
  async customize(main, t) {
    const ok = await confirmAction("Customize the test",
      `${t.name} moves from ${t.file}.json to ${t.table}.json, where you can change it. Generating the tests again will not overwrite it.`, "Move to custom");
    if (!ok) return;
    if (await attempt(() => api(`/tests/${t.file}/${t.name}/customize`, "POST"), "Moved")) {
      await load(main);
      edit(main, state.tests.find((x) => x.name === t.name));
    }
  },
  edit(main, t) {
    edit(main, t);
  },
  async remove(main, t) {
    if (await confirmAction("Delete the test", `${t.name} is removed from ${t.file}.json.`, "Delete")) {
      if (await attempt(() => api(`/tests/${t.file}/${t.name}`, "DELETE", undefined, state.files[t.file] ?? ""), "Deleted")) {
        delete state.results[t.name];
        load(main);
      }
    }
  },
};

async function edit(main, t, draft) {
  const stored = t ? { description: t.description, ...(t.endpoint ? { endpoint: t.endpoint } : {}), steps: t.steps } : EXAMPLE;
  const data = draft?.data ?? stored;
  const name = draft?.name ?? t?.name ?? "";
  const file = draft?.file ?? t?.file ?? (state.filter || "my_table");
  const v = await dialog(t ? `Edit ${t.name}` : "New composed test", `
    <p class="sa-small uk-text-muted">Each step: <code>"METHOD /path": body</code> (<code>null</code> without body), <code>as</code>
      (the id of the user, no password needed), <code>expect</code> (a status, or an object with status, count, row and message;
      without it, a 2xx) and <code>save</code> (values of the response for the next steps, as <code>\${name}</code>).</p>
    <div class="sa-form">
      <div class="sa-field"><label class="uk-form-label" for="t-name">Name</label><input class="uk-input" id="t-name" name="name" value="${esc(name)}" required pattern="\\w+"></div>
      <div class="sa-field"><label class="uk-form-label" for="t-file">File (tests/….json)</label><input class="uk-input" id="t-file" name="file" value="${esc(file)}" required pattern="[\\w-]+"></div>
    </div>
    <div class="sa-field"><label class="uk-form-label" for="t-data">Test (JSON)</label>
      <textarea id="t-data" name="data" class="uk-textarea sa-code" spellcheck="false">${esc(typeof data === "string" ? data : JSON.stringify(data, null, 2))}</textarea></div>
    <div class="sa-toolbar"><button class="uk-button uk-button-default" type="button" id="t-try">Try the steps</button></div>
    <div id="t-result"></div>`, "Save");

  // The dialog is closed: bind "try" is done below, before awaiting, see bindTryInDialog
  if (!v) return;
  let parsed;
  try {
    parsed = JSON.parse(v.data);
  } catch {
    toast("The test is not valid JSON", "error");
    return edit(main, t, { name: v.name, file: v.file, data: v.data });
  }
  const saved = await attempt(() => api(`/tests/${encodeURIComponent(v.file)}/${encodeURIComponent(v.name)}`, "PUT",
    parsed, state.files[v.file] ?? ""), `Saved in tests/${v.file}.json`);
  if (saved) {
    if (t && (t.name !== v.name || t.file !== v.file)) {
      const etag = t.file === v.file ? saved.etag : state.files[t.file] ?? "";
      await attempt(() => api(`/tests/${t.file}/${t.name}`, "DELETE", undefined, etag));
    }
    load(main);
  } else {
    edit(main, t, { name: v.name, file: v.file, data: parsed });
  }
}

// "Try the steps" inside the dialog: runs them rolled back and shows each result
document.addEventListener("click", async (event) => {
  if (event.target.id !== "t-try") return;
  const area = document.querySelector("#t-data");
  let parsed;
  try {
    parsed = JSON.parse(area.value);
  } catch {
    toast("The test is not valid JSON", "error");
    return;
  }
  const res = await attempt(() => api("/tests/try", "POST", { steps: parsed.steps }));
  if (res) {
    document.querySelector("#t-result").innerHTML = stepsDetail(res.steps) +
      (res.steps.length < parsed.steps.length ? `<p class="sa-small uk-text-muted">The next steps were not run.</p>` : "");
  }
});
